#!/usr/bin/env python3
"""Build a small, public-only personal site. Python stdlib; no network or secrets.

Usage: python build.py --out docs
Content and template changes remain ordinary reviewable source edits. This tool
never discovers personal files, publishes a repository, or changes an account.
"""
from __future__ import annotations
import argparse, hashlib, html, json, re, shutil
from pathlib import Path
from urllib.parse import urlsplit

ROOT = Path(__file__).resolve().parent
BASE = 'https://jacob-met.github.io'
STAMP = '2026-09-09'
NAV = [('work.html','Work'),('research.html','Research'),('spire.html','M. Schauz'),('computing.html','Software'),('making.html','Making'),('about.html','About')]
ALLOWED_HOSTS = {'github.com','www.instagram.com','myanimelist.net','www.royalroad.com','www.linkedin.com','www.csulbtbp.org'}
E = html.escape

def safe_url(value: str) -> str:
    if not isinstance(value,str) or len(value)>600 or any(c.isspace() for c in value):
        raise ValueError('Invalid URL')
    u=urlsplit(value)
    if u.scheme!='https' or u.hostname not in ALLOWED_HOSTS or u.username or u.password or u.port or u.query or u.fragment:
        raise ValueError('URL outside the approved public link set')
    return value

def validate(data: dict) -> None:
    if not isinstance(data,dict) or data.get('visibility')!='public':
        raise ValueError('Only explicitly public content can be built')
    if data.get('name')!='Jacob Metoyer' or data.get('byline')!='M. Schauz':
        raise ValueError('Identity differs from the approved public record')
    if set(data)!={'visibility','name','byline','updated','identities','work'}:
        raise ValueError('Unexpected root field: public export must be explicit')
    if not isinstance(data['work'],list) or not isinstance(data['identities'],list):
        raise ValueError('Expected explicit lists')
    seen=set()
    for row in data.get('work',[]):
        if not isinstance(row,dict) or set(row)!={'id','title','category','status','route','summary','role','evidence','limitations','links','visibility','publication_approved'}:
            raise ValueError('Unexpected work field')
        if row.get('visibility')!='public' or row.get('publication_approved') is not True:
            raise ValueError('Work entry lacks public approval')
        ident=row.get('id','')
        if not re.fullmatch(r'[a-z][a-z0-9-]{1,48}',ident) or ident in seen:
            raise ValueError('Invalid or duplicate work id')
        seen.add(ident)
        for key in ('title','summary','status','category','role','evidence','limitations'):
            if not isinstance(row.get(key),str) or not 1<=len(row[key])<=2000:
                raise ValueError(f'Invalid {key}')
        if row['category'] not in ('Research','Fiction','Computing','Making'):
            raise ValueError('Unknown category')
        route=row.get('route','')
        if route not in {x[0] for x in NAV}: raise ValueError('Invalid internal route')
        for link in row.get('links',[]):
            if set(link)!={'label','url'}:raise ValueError('Unexpected link field')
            safe_url(link['url'])
            if not isinstance(link.get('label'),str) or not link['label']:raise ValueError('Missing link label')
    for link in data.get('identities',[]):
        if set(link)!={'label','url'}:raise ValueError('Unexpected identity field')
        safe_url(link['url'])
    if not seen:raise ValueError('Empty public catalogue')

def link(url: str,label: str,cls: str='text-link') -> str:
    safe_url(url)
    return f'<a class="{E(cls)}" href="{E(url,quote=True)}" rel="me noopener">{E(label)} <span aria-hidden="true">↗</span></a>'

def paragraphs(items: list[str]) -> str:
    return ''.join(f'<p>{E(x)}</p>' for x in items)

def section_intro(kicker: str,title: str,body: str='') -> str:
    return f'<header class="page-intro"><p class="eyebrow">{E(kicker)}</p><h1>{E(title)}</h1>'+ (f'<p class="intro">{E(body)}</p>' if body else '')+'</header>'

def layout(name: str,title: str,desc: str,body: str, data: dict) -> str:
    nav=''.join(f'<a href="{p}"'+(' aria-current="page"' if name==p else '')+f'>{E(t)}</a>' for p,t in NAV)
    schema={'@context':'https://schema.org','@type':'Person','name':data['name'],'alternateName':data['byline'],'url':BASE,'sameAs':[x['url'] for x in data['identities']]}
    structured=json.dumps(schema,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e')
    canonical=BASE+'/'+('' if name=='index.html' else name)
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{E(title)} · Jacob Metoyer</title><meta name="description" content="{E(desc,quote=True)}">
<meta name="theme-color" content="#183c31"><meta name="referrer" content="strict-origin-when-cross-origin">
<link rel="canonical" href="{canonical}"><link rel="icon" href="assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="style.css">
<meta property="og:type" content="website"><meta property="og:title" content="{E(title,quote=True)} · Jacob Metoyer"><meta property="og:description" content="{E(desc,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE}/assets/spire-hero.webp">
<script type="application/ld+json">{structured}</script><script src="site.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a><header class="masthead"><a class="wordmark" href="index.html" aria-label="Jacob Metoyer home">Jacob <strong>Metoyer</strong><span class="wordmark-note">an ongoing body of work</span></a><nav aria-label="Main navigation">{nav}</nav></header>
<main id="main">{body}</main>
<footer class="footer"><div><a class="footer-name" href="index.html">Jacob Metoyer</a><p>Research, fiction, software, and making.<br>M. Schauz is my creative byline.</p></div><div class="footer-links"><a href="now.html">Now</a><a href="process.html">AI &amp; authorship</a><a href="credits.html">Sources &amp; credits</a><a href="privacy.html">Privacy</a></div><div class="footer-links"><a href="https://github.com/Jacob-Met" rel="me noopener">GitHub ↗</a><a href="https://www.instagram.com/tornadocos/" rel="me noopener">Cosplay ↗</a><a href="https://myanimelist.net/profile/TornadoZW" rel="me noopener">MyAnimeList ↗</a><small>Revised September 9, 2026<br>Jacob Metoyer / M. Schauz</small></div></footer>
</body></html>'''

def card(row: dict,compact: bool=False) -> str:
    return f'''<article class="work-card" data-category="{E(row['category'])}"><div class="card-top"><span class="category">{E(row['category'])}</span><span class="status">{E(row['status'])}</span></div><h2><a href="{E(row['route'])}#{E(row['id'])}">{E(row['title'])}<span aria-hidden="true">↗</span></a></h2><p>{E(row['summary'])}</p><p class="card-role">{E(row['role'])}</p></article>'''

def project_detail(row: dict) -> str:
    links=' '.join(link(x['url'],x['label']) for x in row.get('links',[]))
    return f'''<article id="{E(row['id'])}" class="project-detail"><div class="detail-label"><p class="eyebrow">{E(row['category'])}</p><span class="status">{E(row['status'])}</span></div><div><h2>{E(row['title'])}</h2><p class="lead">{E(row['summary'])}</p><dl class="evidence"><dt>My part</dt><dd>{E(row['role'])}</dd><dt>What exists</dt><dd>{E(row['evidence'])}</dd><dt>Scope</dt><dd>{E(row['limitations'])}</dd></dl><div class="project-links">{links}</div></div></article>'''

def build(out: Path,data: dict|None=None) -> dict:
    data=json.loads((ROOT/'content.json').read_text(encoding='utf-8')) if data is None else data
    validate(data)
    out=out.resolve()
    if out==ROOT or ROOT.is_relative_to(out):raise ValueError('Output must not replace source')
    allowed_files={'index.html','work.html','research.html','spire.html','computing.html','making.html','about.html','process.html','now.html','credits.html','privacy.html','404.html','style.css','site.js','.nojekyll','robots.txt','sitemap.xml','work.json','build-manifest.json','assets/mark.svg','assets/spire-hero.webp','assets/seamwork.webp','assets/reminder.webp'}
    if out.exists():
        for existing in out.rglob('*'):
            if existing.is_symlink() or (existing.is_file() and existing.relative_to(out).as_posix() not in allowed_files):
                raise ValueError('Output contains unexpected material; refuse to overwrite or publish it')
    out.mkdir(parents=True,exist_ok=True)
    pages={}; work=data['work']
    home='''<section class="hero"><div class="hero-copy"><p class="eyebrow">Researcher. Builder. M. Schauz.</p><h1>A life<br><em>in works.</em></h1><p class="intro">I'm Jacob Metoyer. I research biology and movement, build software, and create fiction as M. Schauz. Sometimes the work is code. Sometimes it's a world, a costume, or a question I want to understand.</p><div class="actions"><a class="button" href="work.html">Explore the work <span aria-hidden="true">↗</span></a><a class="text-link" href="about.html">Meet the person →</a></div></div><figure class="hero-art"><img src="assets/spire-hero.webp" alt="An immense industrial city with glowing windows, pipes, bridges, and falling water; concept artwork for Spire of Octaves" width="1600" height="900" fetchpriority="high"><figcaption><span>From Spire of Octaves</span><a href="spire.html">The world of M. Schauz ↗</a></figcaption><span class="art-label" aria-hidden="true">01 / A world in progress</span></figure></section>
<section class="identity-strip" aria-label="Connected identities"><p>One person.<br><strong>Different ways of making.</strong></p><a href="research.html">Jacob Metoyer<span>research &amp; computation</span></a><a href="spire.html">M. Schauz<span>fiction &amp; imagined worlds</span></a><a href="making.html">tornadocos<span>cosplay &amp; physical making</span></a></section>
<section class="section"><div class="section-heading"><div><p class="eyebrow">Selected work</p><h2>Different doors.<br>The same curiosity.</h2></div><p>Some projects begin with a scientific question. Others begin with a story, a game, or something I want to make with my hands. They don't have to be the same kind of work to belong together.</p></div><div class="work-grid">'''+''.join(card(x) for x in work if x['id'] in ('spire-world','research-movement','capturesuite','cosplay'))+'''</div><a class="text-link end-link" href="work.html">The full public index →</a></section>
<section class="research-band"><p class="eyebrow">A lasting direction</p><div><h2>Biology and medicine<br>aren't a side project.</h2><p>My research interests include the brain, behavior, biological systems, and human movement. I hope to pursue an MD/PhD. Computation is both a way into these questions and an interest with a life of its own.</p><a class="text-link" href="research.html">Research experience &amp; questions →</a></div></section>
<section class="section process-teaser"><p class="eyebrow">On tools and responsibility</p><h2>AI is part of my process.<br><em>The work still has to earn its place.</em></h2><p>I want the results, decisions, revisions, and limitations to be visible. Not every line is hand-written. Not every experiment succeeds. A tool label, in either direction, isn't a substitute for looking closely.</p><a class="text-link" href="process.html">AI, authorship &amp; evidence →</a></section>'''
    pages['index.html']=('A life in works','The connected work of Jacob Metoyer: biology and medicine, computation, fiction as M. Schauz, and cosplay as tornadocos.',home)
    filters='''<div class="filter-wrap" hidden><div class="filters" role="group" aria-label="Filter work by field">'''+''.join(f'<button type="button" data-filter="{x}" aria-pressed="{str(x=="All").lower()}">{x}</button>' for x in ['All','Research','Fiction','Computing','Making'])+'''</div><p id="filter-count" role="status" aria-live="polite"></p></div>'''
    body=section_intro('Public index','The work, in its own forms.','An evolving map—not a claim that every project is finished, or that everything I do is public.')+filters+'<section class="work-grid catalogue" aria-label="Public work">'+''.join(card(x) for x in work)+'</section><aside class="note"><strong>How to read this index.</strong> Public source means there is code to inspect. A research contribution is not a clinical claim. Working manuscripts are not published chapters. The project pages keep those distinctions visible.</aside>'
    pages['work.html']=('Work','A navigable record of research, fiction, software and making by Jacob Metoyer.',body)
    body=section_intro('Biology / medicine / computation','Questions worth staying with.','Biology and medicine are enduring interests—not simply another use case for software. My current direction is toward physician-scientist research, with an MD/PhD as an aspiration.')+'''<section class="research-intro"><div><h2>From behavior to movement.</h2><p>My research experience includes behavioral neuroscience, molecular dynamics and protein modeling, rehabilitation data, and surgical ergonomics. I am interested in how we measure complex biological systems and how computational methods can help us ask better questions about them.</p></div><aside class="education"><p class="eyebrow">Education &amp; training</p><h3>California State University,<br>Long Beach</h3><p>Computer science and physics<br>Biology minor<br>BUILD Scholar</p><p class="small">Undergraduate studies. MD/PhD is a future goal, not a current credential.</p></aside></section>'''+''.join(project_detail(x) for x in work if x['category']=='Research')+'''<aside class="note">These summaries describe my contributions and areas of work. They do not release participant data, confidential research material, or unpublished findings. </aside>'''
    pages['research.html']=('Research','Jacob Metoyer’s research interests and experience in biology, behavioral neuroscience, protein modeling, rehabilitation and human movement.',body)
    body=section_intro('Fiction & worldbuilding / M. Schauz','Spire of Octaves.','Fantasy about the people who keep worlds alive.')+'''<figure class="wide-art"><img src="assets/spire-hero.webp" alt="Spire concept artwork: a vast inhabited industrial interior, layered bridges and amber light" width="1600" height="900"><figcaption>Spire publication artwork. Concept image, not a screenshot of a completed game. <a href="credits.html">Artwork &amp; process notes →</a></figcaption></figure><section class="split-story" id="spire-world"><div><p class="eyebrow">The world</p><h2>Work, warmth,<br>and the cost of being useful.</h2></div><div><p>Spire of Octaves begins with people trying to keep themselves and their households alive inside a vertical city. Pipes, labor, obligations, reputation, and power shape the world as much as its fantastic elements.</p><p>The main narrative follows Dorren and a working-class household. A useful ability draws attention; attention brings people who want a claim on it. The larger world is built to sustain more than one story.</p><p>This is a writing-first project with long-form fiction, shorts, worldbuilding, and visual development. Games, animation, and other ways to inhabit the world are directions of exploration—not finished products presented as facts.</p><p><strong>M. Schauz is the creative byline of Jacob Metoyer.</strong> The name identifies this body of fiction; it is not a separate anonymous identity.</p></div></section><section class="section"><div class="section-heading"><div><p class="eyebrow">Ways into the fiction</p><h2>Stories with their own doors.</h2></div></div><div class="books"><article id="seamwork" class="book"><img src="assets/seamwork.webp" alt="Seamwork cover, credited to M. Schauz" width="400" height="600" loading="lazy"><div><p class="eyebrow">Serial / reader link</p><h2>Seamwork</h2><p>Harl means to stay boring. The road won't let him. A journey with a marriage cart through the Greel becomes a story about the price of using a craft he has been trying not to use.</p><a class="text-link" href="https://www.royalroad.com/fiction/183255/seamwork">Read on Royal Road ↗</a><p class="small">The reader platform is the source for currently available chapters. No release schedule is promised here.</p></div></article><article id="cold-reminder" class="book"><img src="assets/reminder.webp" alt="A Cold Reminder cover, credited to M. Schauz" width="400" height="600" loading="lazy"><div><p class="eyebrow">Working manuscript</p><h2>A Cold Reminder</h2><p>Kler climbs for a release. The gates take memory as toll. A separate short-novel project in the creative archive, with its own cast and central cost.</p><p class="small">In development. A manuscript or export existing locally does not establish a public release.</p></div></article></div><article class="veria-note" id="veria"><div><p class="eyebrow">Working long-form fiction</p><h2>Veria</h2></div><p>A separate long-form book project with its own narrative identity and reading path, alongside the larger Spire body of work.</p></article></section><section class="archive-note"><h2>Behind the visible work</h2><p>The working archive includes the main narrative, these companion projects, standalone shorts, location and language material, editorial revisions, and visual experiments. That breadth is part of the project. Volume alone is not a quality verdict.</p><details><summary>What the manuscript inventory establishes</summary><p>A September 9, 2026 read-only inventory found 425 numbered main-narrative chapter files, 32 Veria files, 12 Seamwork files, and 28 A Cold Reminder files in their designated working chapter directories. Revision directories, duplicate exports, and archived copies were not counted as extra chapters.</p><p>These are source-file counts—not published, final, peer-reviewed, or reader-validated chapters. The site does not automatically publish the writing archive.</p></details></section>'''
    pages['spire.html']=('M. Schauz · Spire of Octaves','Spire of Octaves, Seamwork, Veria and A Cold Reminder: the fiction and worldbuilding of Jacob Metoyer, writing as M. Schauz.',body)
    body=section_intro('Software & computational work','Tools I wanted to exist.','Research instruments, practical interfaces, and systems built out of curiosity. Public code is an invitation to inspect the work, not a blanket claim of completeness.')+''.join(project_detail(x) for x in work if x['category']=='Computing')+'''<aside class="note">Some software uses AI-assisted implementation. The scope, licensing, installation instructions, and current state live in the project repositories. Third-party names and platforms do not imply affiliation or endorsement.</aside>'''
    pages['computing.html']=('Computing','CaptureSuite, CanvasPilot, uma-sim and other public computational work by Jacob Metoyer.',body)
    body=section_intro('Cosplay / objects / culture','Some of it leaves the screen.','Cosplay and making belong beside the research and fiction—not hidden behind them.')+''.join(project_detail(x) for x in work if x['category']=='Making')+'''<section class="split-story"><div><p class="eyebrow">From character to object</p><h2>Making something<br>you can actually wear.</h2></div><div><p>My cosplay work includes CAD, Blender studies, 3D-printable parts, and prop and armor projects inspired by the stories I enjoy. The making archive includes work around Kingdom and Gilgamesh.</p><p>A design file, a print, a fitted costume, and a finished photograph are different milestones. I want the process to show those distinctions rather than treat every render as a completed physical build.</p><p>These are fan works. The original characters and settings belong to their respective creators; a cosplay is not a claim to their intellectual property.</p></div></section><section class="culture"><p class="eyebrow">Watching, reading, playing</p><h2>Taste is part of the story.</h2><p>Anime, manga, and games are interests in their own right. They also feed the worlds I imagine and the things I make. MyAnimeList lives under <strong>TornadoZW</strong>; my cosplay account is <strong>tornadocos</strong>.</p><div class="actions"><a class="button" href="https://myanimelist.net/profile/TornadoZW" rel="me noopener">MyAnimeList ↗</a><a class="text-link" href="https://www.instagram.com/tornadocos/" rel="me noopener">Cosplay on Instagram ↗</a></div></section>'''
    pages['making.html']=('Making & interests','Cosplay as tornadocos, CAD and physical props, anime and manga as TornadoZW: another part of Jacob Metoyer’s body of work.',body)
    body=section_intro('The person behind the work','Jacob Metoyer.','Researcher, builder, writer as M. Schauz, and cosplayer as tornadocos.')+'''<article class="prose"><p class="opening">I don't want to build a life around making all my interests look like one job description.</p><p>Biology, medicine, and computation are enduring centers for me. I care about understanding living systems and hope to pursue an MD/PhD. I also make software, create the Spire of Octaves world, write fiction, build cosplay props, and spend time with anime, manga, and games.</p><p>Sometimes those interests meet. Research needs better software. A costume starts with a character and becomes a modeling problem. A fictional city becomes more convincing when I think seriously about the work that keeps it alive. Sometimes an interest is simply worth pursuing on its own.</p><h2>One person, several names.</h2><p><strong>Jacob Metoyer</strong> is my public name. <strong>M. Schauz</strong> is my fiction byline. <strong>tornadocos</strong> is my cosplay handle, and <strong>TornadoZW</strong> is my MyAnimeList username. They point to the same person, without requiring every space to speak in exactly the same voice.</p><h2>What this site is for.</h2><p>This is an evolving record of what I have made, contributed to, tried, and become interested in. It is not intended to pretend that every experiment succeeded, every draft is finished, or every project belongs under one specialty.</p><p>I want the work to be traceable to me and the process to be legible. I use AI openly. I also want the differences between direction, implementation, collaboration, source material, and validation to remain visible.</p><h2>What I hope comes next.</h2><p>More serious research. Better tools. Fiction worth reading. Worlds worth inhabiting. Things made with care. I expect the shape of the work to change as I learn; the site should have room for that.</p><p><a class="text-link" href="now.html">The current snapshot →</a></p></article>'''
    pages['about.html']=('About','Jacob Metoyer, also writing as M. Schauz: research, computation, fiction, cosplay, and a life led by genuine interests.',body)
    body=section_intro('AI / authorship / accountability','Judge the work. Understand the process.',"I do not think a tool label tells you, by itself, whether something is good.")+'''<article class="prose"><p class="opening">AI expands what I can attempt. It does not remove my responsibility for what I release.</p><p>I use AI in research, software, writing, and design. I don't claim that every line of code or prose was typed by me, or that every image was hand-drawn. My part includes choosing the questions, directing the work, inspecting results, making editorial and engineering decisions, and deciding what is ready to stand behind.</p><p>That does not make the outputs good by definition. More output is not the same as better work. A test count is not universal correctness. A generated reader simulation is not a human audience. An attractive render is not a finished physical object.</p><h2>Different work needs different evidence.</h2><h3>Science</h3><p>Methods, provenance, uncertainty, and the distinction between observations and interpretations matter. Fictional or generated data cannot be presented as observed research data. This site does not publish confidential participant records or claim clinical validation.</p><h3>Software</h3><p>Inspect the source, run the supported examples, and examine the tests and limitations. A demonstrated feature has a scope. AI-assisted implementation needs review just as other implementation does.</p><h3>Fiction and art</h3><p>Read and look closely. Character, language, atmosphere, coherence, and the experience of the work matter. Process transparency is not a substitute for those qualities, nor does a tool label settle them.</p><h3>Making</h3><p>A concept, model, fabrication attempt, fitted object, and finished costume are different stages. Photographs, iteration, and material constraints tell a story that a concept render alone cannot.</p><h2>Credit should be specific.</h2><p>Collaborators, institutions, upstream software, references, and original creators deserve accurate attribution. Using AI is not a claim to have done everyone else's work, and directing a project is not the same as inventing every component.</p><h2>A record, not a victory lap.</h2><p>I want the case for this way of working to come from a growing body of substantive work and visible care. This site is part of making that record inspectable, including the unfinished parts and the things still to learn.</p></article>'''
    pages['process.html']=('AI & authorship','How Jacob Metoyer approaches AI assistance, authorship, credit, evidence, and responsibility across different kinds of work.',body)
    body=section_intro('Now / September 9, 2026','An honest snapshot.','This is a dated editorial snapshot, not an automatically updating activity feed.')+'''<div class="now-grid"><section><p class="eyebrow">Research</p><h2>Biology, movement, and computational methods.</h2><p>Continuing research connected to rehabilitation and surgical ergonomics while developing a longer-term path toward physician-scientist work. The MD/PhD remains an aspiration.</p></section><section><p class="eyebrow">Fiction</p><h2>Giving the world room to grow.</h2><p>Working with the Spire of Octaves body of fiction, its related manuscripts and world material. M. Schauz is now openly connected to Jacob Metoyer.</p></section><section><p class="eyebrow">Software & making</p><h2>Following the problems that hold my attention.</h2><p>Research tools, computational projects, cosplay and physical making remain active interests. Not everything is ready for public release or needs to be.</p></section><section><p class="eyebrow">This record</p><h2>Making the work easier to find.</h2><p>Consolidating public project descriptions, evidence, authorship and links without flattening them into one career title. New entries should bring actual work, not just another announcement.</p></section></div><aside class="note">The public index is deliberately selected. Access to a personal archive is not permission to publish its contents, and an unfinished project isn't made finished by appearing on a website.</aside>'''
    pages['now.html']=('Now','A dated snapshot of Jacob Metoyer’s research, writing, software and creative interests.',body)
    body=section_intro('Sources & credits','Make the connections visible.','A public record should distinguish where a description comes from and what it establishes.')+'''<article class="prose"><h2>Identity</h2><p>Jacob Metoyer, M. Schauz, tornadocos, and TornadoZW are linked here with the account owner's explicit authorization. This site does not claim to speak for an employer, university, laboratory, or platform.</p><h2>Research descriptions</h2><p>Research summaries draw on my CV and project records. They describe my contributions to collaborative work; confidential data and unpublished scientific findings are not included.</p><h2>Public software</h2><p>CaptureSuite, CanvasPilot, and uma-sim descriptions are based on their public repository documentation. The repositories, rather than this site, are the source for installation, licensing, current feature support, and technical limitations.</p><ul><li><a href="https://github.com/Jacob-Met/CaptureSuite">CaptureSuite source and licensing</a></li><li><a href="https://github.com/Jacob-Met/canvaspilot">CanvasPilot source and responsible-use notes</a></li><li><a href="https://github.com/Jacob-Met/uma-sim">uma-sim source and notice</a></li></ul><h2>Spire writing and images</h2><p>Spire material comes from the existing M. Schauz writing and author-site archive. The city image is concept artwork, not a photograph or completed game screenshot. The two covers are existing publication-packaging assets. They have been resized for this site, with unnecessary metadata removed.</p><p>The project uses AI-assisted creative processes. The specific generation model and complete image-generation history are not asserted here. Publication status is not inferred from a local export or cover existing.</p><h2>Cosplay and fan work</h2><p>The linked cosplay account belongs to me. Original characters, franchises, and other creators' designs retain their own rights. This page does not redistribute costume patterns or assets whose licensing has not been established.</p><h2>Website</h2><p>This presentation was built with AI assistance and uses an explicit public-only content record, a small static generator, and no paid runtime or embedded trackers. Website test results establish only the tested presentation and build behavior—not the quality of every project described here.</p></article>'''
    pages['credits.html']=('Sources & credits','Source, authorship, image and attribution notes for Jacob Metoyer’s public body of work.',body)
    body=section_intro('Privacy','A small, static site.')+'''<article class="prose"><p>This site does not include an analytics tracker, newsletter form, advertising pixel, account system, checkout, or embedded social-media feed. Its fonts and presentation assets do not require a third-party font request.</p><p>The hosting provider may process ordinary connection and request information to serve the site. Following an external link takes you to a separate service with its own privacy practices.</p><p>Do not send private research data, patient or participant information, credentials, or sensitive files through a social profile linked here. Public links are not a secure research intake channel.</p></article>'''
    pages['privacy.html']=('Privacy','Privacy notes for this static personal website.',body)
    pages['404.html']=('Not found','This page is not part of the current public record.',section_intro('404',"That page is not here.",'The work may have moved, or the link may be incomplete.')+'<p class="back-home"><a class="button" href="index.html">Return home →</a></p>')
    for name,(title,desc,body) in pages.items():
        (out/name).write_text(layout(name,title,desc,body,data),encoding='utf-8',newline='\n')
    for name in ['style.css','site.js']:
        shutil.copyfile(ROOT/name,out/name)
    (out/'assets').mkdir(exist_ok=True)
    if (ROOT/'assets').exists():
        for f in (ROOT/'assets').iterdir():
            if f.is_file() and f.name in ('mark.svg','spire-hero.webp','seamwork.webp','reminder.webp'):
                shutil.copyfile(f,out/'assets'/f.name)
    (out/'.nojekyll').write_text('',encoding='utf-8',newline='\n')
    (out/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {BASE}/sitemap.xml\n',encoding='utf-8',newline='\n')
    sm='<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{BASE}/{"" if p=="index.html" else p}</loc><lastmod>{STAMP}</lastmod></url>' for p in pages if p!='404.html')+'</urlset>'
    (out/'sitemap.xml').write_text(sm,encoding='utf-8',newline='\n')
    (out/'work.json').write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8',newline='\n')
    manifest={str(f.relative_to(out)).replace('\\','/'):hashlib.sha256(f.read_bytes()).hexdigest() for f in sorted(out.rglob('*')) if f.is_file() and f.name!='build-manifest.json'}
    (out/'build-manifest.json').write_text(json.dumps({'schema':1,'date':STAMP,'sha256':manifest},indent=2)+'\n',encoding='utf-8',newline='\n')
    return {'pages':len(pages),'public_work_entries':len(work),'output':str(out),'files':len(manifest)+1}

